<?php $pageTitle='Manajemen Pesan'; require '_header.php'; require_dongle();
$uid=$_SESSION['user_id']; $msg='';
function vig($text,$key,$decrypt=false){$key=preg_replace('/[^a-z]/i','',strtolower($key));if($key==='')throw new Exception('Kunci Vigenere wajib diisi.');$out='';$j=0;for($i=0;$i<strlen($text);$i++){ $c=$text[$i];if(ctype_alpha($c)){$base=ctype_upper($c)?65:97;$k=ord($key[$j++%strlen($key)])-97;$v=ord($c)-$base;$out.=chr(($v+($decrypt?-$k:$k)+26)%26+$base);}else $out.=$c;}return $out;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim($_POST['title']);$plain=$_POST['message'];$v=vig($plain,$_POST['vkey']);$cipher=encrypt_data($v);$s=db()->prepare('INSERT INTO messages(user_id,title,ciphertext) VALUES(?,?,?)');$s->execute([$uid,$title,$cipher]);log_activity('MESSAGE_ENCRYPTED',$title);$msg='Pesan berhasil dienkripsi dan disimpan.';}catch(Throwable $e){$msg=$e->getMessage();}}
$s=db()->prepare('SELECT * FROM messages WHERE user_id=? ORDER BY id DESC');$s->execute([$uid]);$rows=$s->fetchAll();
?><div class="panel"><h2>Super Encryption</h2><p class="muted">Tahap 1: Vigenere Cipher (klasik). Tahap 2: AES-256-GCM (modern).</p><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Judul pesan</label><input name="title" required><label>Pesan teks</label><textarea name="message" rows="4" required></textarea><label>Kunci Vigenere</label><input name="vkey" required placeholder="Contoh: KRIPTO"><button class="btn">Enkripsi & Simpan</button></form></div>
<div class="panel"><h2>Pesan tersimpan</h2><?php if(!$rows):?><p class="muted">Belum ada pesan.</p><?php endif;?><?php foreach($rows as $r):?><div class="record"><div><b><?=e($r['title'])?></b><small><?=e($r['created_at'])?></small><code><?=e(substr($r['ciphertext'],0,70))?>…</code></div><form method="post" action="../api/decrypt_message.php" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="vkey" placeholder="Kunci Vigenere" required><button class="btn secondary">Dekripsi</button></form></div><?php endforeach;?></div><?php require '_footer.php';?>
